import json
import sys
from pathlib import Path


TASK_ROOT = Path(__file__).resolve().parent
REPORT = TASK_ROOT / "outputs" / "public_reproduction_report.json"


def write_report(payload: dict[str, object], code: int) -> int:
    REPORT.parent.mkdir(exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT.write_text(text, encoding="utf-8")
    print(text, end="")
    return code


def main() -> int:
    try:
        from workflow.advection_experiment import run_public_workflow

        config = json.loads((TASK_ROOT / "fixtures" / "public_cases.json").read_text())
        result = run_public_workflow(TASK_ROOT, config)
    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    finite = bool(result["finite"])
    status = "workflow_completed" if finite else "pre_fix_expected_failure"
    return write_report(
        {
            "schema_version": "1.0",
            "status": status,
            "observation": result,
        },
        0 if finite else 1,
    )


if __name__ == "__main__":
