import numpy as np, pybamm
x = pybamm.SpatialVariable('x', domain='domain', coord_sys='cartesian')
u = pybamm.Variable('u', domain='domain')
# du/dt = div(grad u) with Dirichlet 0 and 1 -> steady linear profile
bcs = {u: {'left': (pybamm.Scalar(0.0), 'Dirichlet'), 'right': (pybamm.Scalar(1.0), 'Dirichlet')}}
geometry = {'domain': {x: {'min': pybamm.Scalar(0), 'max': pybamm.Scalar(1)}}}
mesh = pybamm.Mesh(geometry, {'domain': pybamm.Uniform1DSubMesh}, {x: 20})
disc = pybamm.Discretisation(mesh, {'domain': pybamm.FiniteVolume()})
model = pybamm.BaseModel()
model.rhs = {u: pybamm.div(pybamm.grad(u))}
model.initial_conditions = {u: pybamm.Scalar(0)}
model.boundary_conditions = bcs
model.variables = {'u': u, 'x': x}
proc = disc.process_model(model, inplace=False)
sol = pybamm.ScipySolver(method='BDF').solve(proc, np.linspace(0,50,100))
uf = sol['u'].entries[:,-1]; xs = sol['x'].entries[:,0]
print('  diffusion steady max err vs linear:', round(float(np.max(np.abs(uf - xs))),6), '(expect ~0)')
